CREATE VIEW dbo.IV_Q$DEMONSTRACAO_JD ( SeqPessoa, Pessoa, SeqQuestionario, SeqFormulario, Formulario, DtaRealizacao, UsuInclusao, DtaAlteracao, UsuAlteracao,  Observacao, SeqHistorico, Resultado, Processo, Departamento, LinkDocto, LinkNro, LinkSerie , CONCESSIONARIO, LOJA, MODELO_DEMONSTRACAO, CHASSI, CLIENTE, FAZENDA, CULTURA, DATA_DEMONSTRACAO, RESPONSAVEL, CELULAR_RESPONSAVEL, E_MAIL_CLIENTE, CNPJ, OPERACAO, IMPLEMENTO_AGRICOLA, HORIMETRO_INICIAL, HORIMETRO_FINAL, DIESEL_GASTO, NIVEL_DO_TANQUE, AREA_TRABALHADA, DEPOIMENTO_DO_CLIENT, CELULAR_DO_RESPONSAV, HORIMETROINICIAL, HORIMETROFINAL, NIVEL_TANQUE, OPERACAO1, SERA_NECESSARIO_ENTR, CLIENTE_JOHN_DEERE, POSSUI_JD, ITEM_TECNOLOGIA, VALOR_DEMONSTRACAO, QTD_PRODUTOS_NEG, OBJETIVO_DEMO)    AS SELECT TBASE.SEQPESSOA, TBASE.NOMERAZAO, QST.SEQQUESTIONARIO, FRM.SEQFORMULARIO, FRM.DESCRICAO, QST.DTAREALIZACAO, QST.USUINCLUSAO, QST.DTAALTERACAO, QST.USUALTERACAO, QST.OBS, QST.SEQHISTORICO, QST.RESULTADO, QST.PROCESSO, QST.DEPARTAMENTO, QST.LINKDOCTO, QST.LINKNRO, QST.LINKSERIE , TABF.CONCESSIONARIO, TABF.LOJA, TABF.MODELO_DEMONSTRACAO, TABF.CHASSI, TABF.CLIENTE, TABF.FAZENDA, TABF.CULTURA, TABF.DATA_DEMONSTRACAO, TABF.RESPONSAVEL, TABF.CELULAR_RESPONSAVEL, TABF.E_MAIL_CLIENTE, TABF.CNPJ, TABF.OPERACAO, TABF.IMPLEMENTO_AGRICOLA, TABF.HORIMETRO_INICIAL, TABF.HORIMETRO_FINAL, TABF.DIESEL_GASTO, TABF.NIVEL_DO_TANQUE, TABF.AREA_TRABALHADA, TABF.DEPOIMENTO_DO_CLIENT, TABF.CELULAR_DO_RESPONSAV, TABF.HORIMETROINICIAL, TABF.HORIMETROFINAL, TABF.NIVEL_TANQUE, TABF.OPERACAO1, TABF.SERA_NECESSARIO_ENTR, TABF.CLIENTE_JOHN_DEERE, TABF.POSSUI_JD, TABF.ITEM_TECNOLOGIA, TABF.VALOR_DEMONSTRACAO, TABF.QTD_PRODUTOS_NEG, TABF.OBJETIVO_DEMO   FROM IV_Q_DEMONSTRACAO_JD TABF 	JOIN IV_QUESTIONARIO QST ON QST.SEQQUESTIONARIO =  TABF.SEQQUESTIONARIO 	JOIN IV_FORMULARIO FRM ON   FRM.SEQFORMULARIO = QST.SEQFORMULARIO 	JOIN GE_PESSOA TBASE ON TBASE.SEQPESSOA = QST.SEQPESSOA  